sys_ui_action.script:
(function executeRule(current, previous) {
    try {
        var orchestrator = new x_snc_ai_sdlc.AIOrchestrator(current);
        orchestrator.generateCode();
        gs.addInfoMessage('ServiceNow code generated successfully. View the Generated Code field on the AI Manifest record.');
    } catch (e) {
        gs.addErrorMessage('Code generation failed: ' + e.message + '. Check the Orchestration Log on the AI Manifest record.');
    }
    action.setRedirectURL(current);
})(current, previous);
